PH = ["#e53935", "#e53935", "#e53935", "#ef6c00", "#fb8c00", "#fdd835", "#c0ca33", "#43a047", "#26a69a", "#1e88e5", "#3949ab", "#5e35b1", "#7b1fa2", "#8e24aa", "#6a1b9a"]
def phstrip(a, n, b):
    cells = "".join(f'<rect x="{i*34}" y="0" width="34" height="30" fill="{c}"/><text x="{i*34+17}" y="20" text-anchor="middle" font-size="12" font-weight="700" fill="#fff">{i}</text>' for i, c in enumerate(PH))
    return f'<svg class="svgc" viewBox="0 0 510 52" width="470"><g>{cells}</g><text x="2" y="46" font-size="10" fill="#555">{a}</text><text x="255" y="46" text-anchor="middle" font-size="10" fill="#555">{n}</text><text x="508" y="46" text-anchor="end" font-size="10" fill="#555">{b}</text></svg>'
def timeline(labels):
    segs = [(0, 5, "#e57373"), (5, 13, "#81c784"), (13, 14, "#ffd54f"), (14, 28, "#ba68c8")]
    out = "".join(f'<rect x="{a/28*480+10}" y="6" width="{(b-a)/28*480}" height="26" rx="4" fill="{c}"/><text x="{(a+b)/2/28*480+10}" y="23" text-anchor="middle" font-size="10.5" font-weight="700" fill="#fff">{t}</text>' for (a, b, c), t in zip(segs, labels))
    return f'<svg class="svgc" viewBox="0 0 500 40" width="480">{out}</svg>'

